import type { Register } from 'claude-code'

const RULES = `Responda sempre em linguagem simples e fácil de entender, como se explicasse a alguém sem formação técnica.
- Evite jargão; se um termo técnico for inevitável, explique-o em poucas palavras.
- Frases curtas, voz ativa, palavras do dia a dia.
- Vá direto ao ponto: primeiro a resposta, depois o necessário.
- Use exemplos ou comparações simples quando ajudar.
- Mantenha o idioma do usuário. Isto vale para o texto ao usuário, não para código ou comandos.`

export const register: Register = on => {
  let isOn = true

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'simples', description: 'Liga/desliga respostas em linguagem simples' })
    $.ui.status('Respostas simples: ligado')

    return next(e)
  })

  on('command.run', { command: 'simples' }, $ => {
    isOn = !isOn
    $.ui.status(isOn ? 'Respostas simples: ligado' : undefined)

    return { text: isOn ? 'Respostas simples LIGADO.' : 'Respostas simples DESLIGADO.' }
  })

  on('prompt.compose', async ($, e, next) => {
    const r = await next(e)

    return isOn ? { sections: [...r.sections, { id: 'plain-answers', text: RULES, scope: 'session' as const }] } : r
  })
}

